<section class="card"><h2>Verificări automate ale mediului</h2><p class="fine">Aceste rezultate descriu serverul curent. Nu certifică livrarea SMS, dispozitivele sau un alt furnizor de găzduire.</p><?php foreach($diagnostics as $diagnostic):?><div class="list-row"><span><b><?=e($diagnostic['label'])?></b><small><?=e($diagnostic['detail'])?></small></span><span class="pill"><?=$diagnostic['ok']?'✓ Disponibil':'De configurat'?></span></div><?php endforeach ?></section>
<?php if(Alba\Auth::phoneVerificationRequired()):?><section class="card"><h2>Trimite un SMS de test</h2><p>Doar la cerere, către numărul introdus. Un furnizor SMS real poate taxa acest mesaj.</p><form data-command="test-sms" class="inline-form"><label>Telefon destinatar<input name="phone" type="tel" placeholder="+407…" required></label><button class="button secondary">Solicită trimiterea mesajului de test</button></form></section>
<?php endif ?><section class="card"><h2>Dovezi înainte de lansare</h2><p class="fine">Înregistrează mediul, data, rezultatul și persoana care a verificat. Bifarea unui rezultat nu înlocuiește testul efectiv.</p><?php $recorded=array_column($checks,null,'check_key');foreach(Alba\Readiness::CHECKS as $key=>$label):if($key==='sms'&&!Alba\Auth::phoneVerificationRequired())continue;$record=$recorded[$key]??null;?><details class="acceptance-check"><summary><?=e($label)?> · <?=e(Alba\Labels::state($record['status']??'pending'))?></summary><form class="stack" data-command="readiness-check"><input name="check" type="hidden" value="<?=e($key)?>"><label>Rezultat<select name="status"><?php foreach(['pending'=>'De verificat','passed'=>'Verificat cu succes','failed'=>'Probleme găsite'] as $value=>$text):?><option value="<?=e($value)?>" <?=($record['status']??'pending')===$value?'selected':''?>><?=e($text)?></option><?php endforeach ?></select></label><label>Mediu, rezultat și dovadă<textarea name="notes" minlength="5" required><?=e($record['notes']??'')?></textarea></label><?php if($record):?><p class="fine">Ultima înregistrare: <?=e(localtime_ro($record['checked_at']))?> · administrator #<?=e($record['actor_id'])?></p><?php endif ?><button class="button secondary">Salvează dovada</button></form></details><?php endforeach ?></section>
